package com.healthcoach.app
import android.content.Context;import android.net.Uri;import androidx.documentfile.provider.DocumentFile;import org.json.*;import kotlin.math.roundToInt
object HealthExporter{private fun med(v:List<Double>):Double?{if(v.isEmpty())return null;val s=v.sorted();val m=s.size/2;return if(s.size%2==0)(s[m-1]+s[m])/2 else s[m]}
private fun base(n:Int,a:List<Day>)=JSONObject().apply{val s=a.take(n);put("sleepMinutes",med(s.mapNotNull{it.sleep?.toDouble()}));put("restingHeartRate",med(s.mapNotNull{it.resting}));put("hrvRmssdMs",med(s.mapNotNull{it.hrv}));put("respiratoryRate",med(s.mapNotNull{it.resp}));put("steps",med(s.map{it.steps.toDouble()}))}
fun current(s:Snapshot):JSONObject{val d=s.days.first();val b7=base(7,s.days);val b30=base(30,s.days);val b90=base(90,s.days);var sc=75.0;b30.optDouble("sleepMinutes",Double.NaN).takeIf{!it.isNaN()&&d.sleep!=null}?.let{sc+=((d.sleep!!-it)/60*5).coerceIn(-15.0,10.0)};b90.optDouble("hrvRmssdMs",Double.NaN).takeIf{!it.isNaN()&&d.hrv!=null&&it>0}?.let{sc+=((d.hrv!!/it-1)*30).coerceIn(-12.0,12.0)};b30.optDouble("restingHeartRate",Double.NaN).takeIf{!it.isNaN()&&d.resting!=null}?.let{sc-=((d.resting!!-it)*2).coerceIn(-8.0,12.0)};val score=sc.roundToInt().coerceIn(0,100);return JSONObject().put("schemaVersion",3).put("generatedAt",s.generatedAt).put("date",d.date).put("app","HealthCoach").put("appVersion","2.0.0").put("current",JSONObject().put("sleepStart",s.sleepStart).put("sleepEnd",s.sleepEnd).put("sleepMinutes",d.sleep).put("lightMinutes",d.light).put("deepMinutes",d.deep).put("remMinutes",d.rem).put("restingHeartRate",d.resting).put("hrvRmssdMs",d.hrv).put("respiratoryRate",d.resp).put("stepsToday",d.steps).put("distanceTodayMeters",d.distance)).put("baseline7d",b7).put("baseline30d",b30).put("baseline90d",b90).put("recovery",JSONObject().put("score",score).put("label",if(score>=75)"Bonne" else if(score>=60)"Moyenne" else "Faible")).put("historyDaysAvailable",s.days.count{it.sleep!=null||it.resting!=null})}
fun history(s:Snapshot)=JSONObject().put("schemaVersion",2).put("generatedAt",s.generatedAt).put("days",JSONArray().apply{s.days.forEach{d->put(JSONObject().put("date",d.date).put("sleepMinutes",d.sleep).put("restingHeartRate",d.resting).put("hrvRmssdMs",d.hrv).put("respiratoryRate",d.resp).put("steps",d.steps).put("distanceMeters",d.distance))}})
fun status(s:Snapshot)=JSONObject().put("schemaVersion",2).put("generatedAt",s.generatedAt).put("connected",true).put("instructionsForChatGPT","Lire healthcoach_current.json en priorité puis healthcoach_history.json. Vérifier generatedAt.")
fun write(c:Context,u:String,n:String,j:JSONObject){val root=DocumentFile.fromTreeUri(c,Uri.parse(u))?:error("Dossier inaccessible");root.findFile(n)?.delete();val f=root.createFile("application/json",n)?:error("Création impossible");c.contentResolver.openOutputStream(f.uri,"w")!!.bufferedWriter().use{it.write(j.toString(2))}}}